1	import { access, cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
2	import { spawn } from 'node:child_process';
3	import { basename, dirname, join, relative, resolve } from 'pathe';
4	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
5	import {
6		ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS,
7		ANGULAR_TINY_TRANSLATOR_FIXTURE,
8		ANGULAR_TINY_TRANSLATOR_MIGRATED_LANE_CHAIN,
9		ANGULAR_TINY_TRANSLATOR_SOURCE,
10		parseWitnessAngularTinyTranslatorReceipt,
11		renderWitnessAngularTinyTranslatorReceipt,
12		WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
13		WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE,
14		WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE,
15		WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES,
16		WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE,
17		WITNESS_ANGULAR_TINY_TRANSLATOR_MIGRATION_FINDINGS,
18		WITNESS_ANGULAR_TINY_TRANSLATOR_RECORDED_AMENDMENTS,
19		WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
20		WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA,
21		WITNESS_ANGULAR_TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
22		WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
23		WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES,
24		witnessAngularTinyTranslatorBehaviorDigest,
25		witnessAngularTinyTranslatorDigest,
26		witnessAngularTinyTranslatorRawDigest,
27		type WitnessAngularTinyTranslatorMutation,
28		type WitnessAngularTinyTranslatorReceipt,
29		type WitnessAngularTinyTranslatorRun,
30	} from '../../../core/src/receipts/witness-angular-tiny-translator.ts';
31	import {
32		WITNESS_DOWNLOAD_CAPTURE_RULE,
33		WITNESS_FILE_INPUT_LOAD_RULE,
34	} from '../../../core/src/receipts/witness-real-app.ts';
35	import {
36		executeAngularTinyTranslatorWitnessRun,
37		TINY_TRANSLATOR_MUTATION_SEAM,
38		WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS,
39		WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS,
40	} from './real-app-run.ts';
41	import { verifyLinkedWitnessProvenance } from './provenance.ts';
42	
43	const root = resolve(import.meta.dirname, '../../../..');
44	const fixtureEvidence = join(root, 'evidence/runs/angular-tiny-translator-v0-12-0');
45	const witnessEvidence = join(root, 'evidence/runs/witness-angular-tiny-translator-v0-12-0');
46	const stageRoot = join(root, '.versionless/stage/witness-angular-tiny-translator-v0-12-0');
47	/**
48	 * The migrated lane's build tree, and the output root the u19k record pins as
49	 * canonical. The tree is a working directory rather than committed bytes, so
50	 * this proof cannot assume it survived: {@link migratedLaneRoot} regenerates it
51	 * from the committed flow when it is absent and, either way, refuses to serve
52	 * it until it matches the inventory the record published.
53	 *
54	 * The root is `dist-13`, the third the browser phase produced. u17d's `dist-7`
55	 * is a green, deterministic build whose artifact throws before Angular
56	 * bootstraps; u19f's `dist-11` mounts and silently discards a typed translation;
57	 * u19k's `dist-13` mounts and keeps it. Each supersession is by reference and
58	 * each was forced by a measurement no build lane could make.
59	 */
60	const migratedStage = join(root, '.versionless/stage/angular-tiny-translator-v0-12-0-u17b');
61	const sourceOutputs = {
62		baseline: join(
63			root,
64			'.versionless/cache/angular-tiny-translator-v0-12-0-baseline/app/dist/rebuild-1',
65		),
66		migrated: join(migratedStage, 'dist-13'),
67	} as const;
68	/** The build the u19k record pins for the canonical output root. */
69	const MIGRATED_BUILD_COMMAND = 'npx ng build --configuration production' as const;
70	const laneFileCounts = { baseline: 524, migrated: 524 } as const;
71	
72	type InventoryEntry = { path: string; sha256: string; bytes: number };
73	
74	async function exists(path: string): Promise<boolean> {
75		return access(path).then(
76			() => true,
77			() => false,
78		);
79	}
80	
81	async function files(directory: string): Promise<string[]> {
82		const output: string[] = [];
83		for (const entry of await readdir(directory, { withFileTypes: true })) {
84			const path = join(directory, entry.name);
85			if (entry.isDirectory()) output.push(...(await files(path)));
86			else if (entry.isFile()) output.push(path);
87		}
88		return output.sort();
89	}
90	
91	/** Every file of an emitted artifact, addressed exactly as the u19k record does. */
92	async function inventoryOf(rootDirectory: string): Promise<InventoryEntry[]> {
93		const entries: InventoryEntry[] = [];
94		for (const file of await files(rootDirectory)) {
95			const bytes = await readFile(file);
96			entries.push({
97				path: relative(rootDirectory, file),
98				sha256: sha256(bytes),
99				bytes: bytes.length,
100			});
101		}
102		return entries;
103	}
104	
105	/** The pinned migrated build record, re-read rather than restated. */
106	async function migratedLaneRecord(): Promise<{
107		inventory: InventoryEntry[];
108		inventorySha256: string;
109	}> {
110		const pinned = ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.find(
111			(receipt) => receipt.lane === 'migrated',
112		);
113		if (pinned === undefined) throw new Error('TinyTranslator migrated lane binding is absent');
114		const bytes = await readFile(join(root, pinned.path));
115		if (sha256(bytes) !== pinned.sha256)
116			throw new Error(`TinyTranslator bound build receipt bytes drifted: ${pinned.path}`);
117		const record = JSON.parse(bytes.toString('utf8')) as {
118			inventory?: InventoryEntry[];
119			determinism?: { inventorySha256?: string };
120		};
121		const inventory = record.inventory;
122		const inventorySha256 = record.determinism?.inventorySha256;
123		if (!Array.isArray(inventory) || typeof inventorySha256 !== 'string')
124			throw new Error('TinyTranslator migrated lane record publishes no inventory to verify');
125		return { inventory, inventorySha256 };
126	}
127	
128	/**
129	 * The digest the u19k record computed over its own inventory: the pretty-printed
130	 * JSON array with a trailing newline, exactly as the recording flow wrote it.
131	 * Recomputing it here rather than accepting the record's own number is what
132	 * makes the comparison a check instead of a restatement.
133	 */
134	function inventoryDigest(inventory: readonly InventoryEntry[]): string {
135		return sha256(`${JSON.stringify(inventory, null, 2)}\n`);
136	}
137	
138	async function run(command: string, args: readonly string[], cwd: string): Promise<void> {
139		await new Promise<void>((settle, fail) => {
140			const child = spawn(command, [...args], {
141				cwd,
142				stdio: 'ignore',
143				env: {
144					...process.env,
145					VERSIONLESS_NETWORK_MODE: 'offline',
146					NPM_CONFIG_OFFLINE: 'true',
147				},
148			});
149			child.on('error', fail);
150			child.on('close', (code) =>
151				code === 0
152					? settle()
153					: fail(new Error(`TinyTranslator regeneration command failed: ${command} (${code})`)),
154			);
155		});
156	}
157	
158	/**
159	 * The migrated lane's canonical output root, regenerated when it is missing and
160	 * verified either way.
161	 *
162	 * The regeneration is the same offline production build the u19k record pins,
163	 * run over the same staged application tree that record itemises; nothing is
164	 * re-migrated here, because the migration is already applied in that tree. The
165	 * verification is what the proof actually rests on: the emitted inventory has
166	 * to reproduce the record's own 524-file inventory, file for file and digest
167	 * for digest, and its digest has to reproduce the record's `inventorySha256`.
168	 * A tree that regenerated differently is refused rather than served.
169	 */
170	async function migratedLaneRoot(): Promise<string> {
171		const record = await migratedLaneRecord();
172		if (!(await exists(sourceOutputs.migrated))) {
173			const application = join(migratedStage, 'app');
174			if (!(await exists(application)))
175				throw new Error(
176					'TinyTranslator migrated lane cannot be regenerated: the staged application tree is absent',
177				);
178			const [command, ...args] = MIGRATED_BUILD_COMMAND.split(' ');
179			await run(command!, [...args, '--output-path', sourceOutputs.migrated], application);
180		}
181		const emitted = await inventoryOf(sourceOutputs.migrated);
182		const emittedDigest = inventoryDigest(emitted);
183		if (canonicalize(emitted) !== canonicalize(record.inventory))
184			throw new Error(
185				`TinyTranslator migrated lane inventory differs from the pinned record: ${emittedDigest} against ${record.inventorySha256}`,
186			);
187		if (emittedDigest !== record.inventorySha256)
188			throw new Error(
189				`TinyTranslator migrated lane inventory digest differs: ${emittedDigest} against ${record.inventorySha256}`,
190			);
191		return sourceOutputs.migrated;
192	}
193	
194	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
195		const migrated = await migratedLaneRoot();
196		const lanes = join(stageRoot, 'lanes');
197		await rm(lanes, { recursive: true, force: true });
198		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
199		const outputs = { baseline: sourceOutputs.baseline, migrated } as const;
200		for (const lane of ['baseline', 'migrated'] as const) {
201			if (!(await exists(outputs[lane])))
202				throw new Error(`TinyTranslator ${lane} production output is absent`);
203			await mkdir(dirname(staged[lane]), { recursive: true });
204			await cp(outputs[lane], staged[lane], { recursive: true, force: false });
205			const stagedFiles = await files(staged[lane]);
206			if (stagedFiles.length !== laneFileCounts[lane])
207				throw new Error(
208					`TinyTranslator ${lane} lane file count differs: ${stagedFiles.length} against ${laneFileCounts[lane]}`,
209				);
210		}
211		return staged;
212	}
213	
214	async function executeRuns(
215		lanes: Record<'baseline' | 'migrated', string>,
216	): Promise<WitnessAngularTinyTranslatorRun[]> {
217		const runs: WitnessAngularTinyTranslatorRun[] = [];
218		for (const lane of ['baseline', 'migrated'] as const)
219			for (const pass of [1, 2] as const) {
220				const raw = await executeAngularTinyTranslatorWitnessRun({
221					lane,
222					pass,
223					laneRoot: lanes[lane],
224					receiptRoot: join(stageRoot, 'receipts'),
225				});
226				const candidate = raw as WitnessAngularTinyTranslatorRun;
227				if (candidate.semanticDigest !== witnessAngularTinyTranslatorRawDigest(candidate))
228					throw new Error(`TinyTranslator ${lane} pass ${pass} raw digest differs`);
229				runs.push({
230					...candidate,
231					behaviorDigest: witnessAngularTinyTranslatorBehaviorDigest(candidate),
232				});
233			}
234		if (new Set(runs.map((entry) => entry.behaviorDigest)).size !== 1)
235			throw new Error('TinyTranslator baseline/migrated behavior parity differs');
236		return runs;
237	}
238	
239	/**
240	 * Byte mutation on the migrated build.
241	 *
242	 * The seam is the visible label of the control that opens the file picker: a
243	 * string a reader sees, asserted exactly by the journey on the create-project
244	 * route, and the name of the very mechanism this vertical exists to exercise.
245	 * The uniqueness demanded here is the corpus discipline — exactly one served
246	 * module may carry it, exactly once — so overwriting it in place cannot be
247	 * absorbed by a second copy elsewhere in the bundle.
248	 */
249	async function semanticMutation(
250		laneRoot: string,
251		behaviorDigest: string,
252	): Promise<WitnessAngularTinyTranslatorMutation> {
253		const expected = Buffer.from(TINY_TRANSLATOR_MUTATION_SEAM);
254		const candidates: Array<{ path: string; offset: number }> = [];
255		for (const path of await files(laneRoot)) {
256			const bytes = await readFile(path);
257			const offset = bytes.indexOf(expected);
258			if (offset < 0) continue;
259			if (bytes.lastIndexOf(expected) !== offset)
260				throw new Error('TinyTranslator semantic seam is not unique within its file');
261			candidates.push({ path, offset });
262		}
263		const target = candidates[0];
264		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
265			throw new Error('TinyTranslator semantic seam is not a single served module');
266		const before = await readFile(target.path);
267		const mutated = Buffer.from(before);
268		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
269		const beforeSha256 = sha256(before);
270		const mutatedSha256 = sha256(mutated);
271		let intendedFailure = false;
272		try {
273			await writeFile(target.path, mutated);
274			try {
275				await executeAngularTinyTranslatorWitnessRun({
276					lane: 'migrated',
277					pass: 1,
278					laneRoot,
279					receiptRoot: join(stageRoot, 'mutation-receipt'),
280				});
281			} catch (error) {
282				const message = error instanceof Error ? error.message : String(error);
283				intendedFailure = message.includes(TINY_TRANSLATOR_MUTATION_SEAM);
284			}
285		} finally {
286			await writeFile(target.path, before);
287		}
288		const afterRestoreSha256 = sha256(await readFile(target.path));
289		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
290			throw new Error('TinyTranslator semantic mutation was not exact red and byte-restored');
291		const restored = (await executeAngularTinyTranslatorWitnessRun({
292			lane: 'migrated',
293			pass: 1,
294			laneRoot,
295			receiptRoot: join(stageRoot, 'restoration-receipt'),
296		})) as WitnessAngularTinyTranslatorRun;
297		const restoredBehaviorDigest = witnessAngularTinyTranslatorBehaviorDigest(restored);
298		if (restoredBehaviorDigest !== behaviorDigest)
299			throw new Error('TinyTranslator restored browser behavior differs');
300		return {
301			failure: 'witness-semantic-assertion',
302			intendedFailure: true,
303			lane: 'migrated',
304			seam: TINY_TRANSLATOR_MUTATION_SEAM,
305			path: relative(laneRoot, target.path),
306			offset: target.offset,
307			beforeSha256,
308			mutatedSha256,
309			afterRestoreSha256,
310			restoredByteIdentically: true,
311			restoredRun: 'pass',
312			restoredBehaviorDigest,
313		};
314	}
315	
316	/**
317	 * The nonclaims this proof publishes. Each one names something a reader could
318	 * otherwise assume from the rest of the receipt and states plainly that it is
319	 * not established here.
320	 */
321	export const WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS: readonly string[] = Object.freeze([
322		'This is one Angular lineage under direct Witness and does not establish generic Angular, Angular CLI 1.5, `.angular-cli.json` workspaces, or `@angular-devkit/build-angular:browser` support.',
323		'The Angular lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
324		'There is no backend and nothing was stubbed or seeded by the harness. The project the journey works on is created by the application itself, from a file this proof hands its own file input, and everything it keeps it keeps in browser local storage.',
325		'The translation file handed to the page is synthetic and authored for this proof. It carries no upstream project’s strings and no third party’s translated content, and it is bound by name, length and digest so a journey cannot quietly load a different one.',
326		'The file the page produced is read back by name, byte length and digest, and its content is asserted rather than published: a produced translation file is the application’s data, not this receipt’s.',
327		'Neither lane ends up with the Material Icons glyphs, and the two lanes fail to get them differently. Both degradations are measured and recorded rather than masked, and neither is a regression of the migration: the font seam is answered inside the browser context so that nothing leaves the machine.',
328		'Two of the four rendered-appearance probes are declared to differ across the eleven-major lift and are checked in both directions — a probe outside the declaration that differs fails the run, and a declared difference that stopped being real fails it too.',
329		'Byte parity across the lanes is not claimed and is recorded separately by the bound build receipts; eleven majors of bundler produce different file names and different byte counts by construction.',
330		'Neither build ships a service worker, and BOTH attempt to register one. The application registers at the literal `%BASE_HREF%ngsw-worker.js` — a placeholder upstream substitutes in a separate npm script that `ng build` never runs — and the request is answered 400 in both lanes. It is an era defect that survives the migration: the migration did not introduce it and no capability here repaired it, and it is recorded rather than suppressed.',
331		'Locality is process-scoped and does not establish operating-system-wide isolation.',
332		'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
333	]);
334	
335	async function bindCanonicalReceipts(): Promise<
336		WitnessAngularTinyTranslatorReceipt['canonicalReceipts']
337	> {
338		return await Promise.all(
339			ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.map(async (pinned) => {
340				const bytes = await readFile(join(root, pinned.path));
341				const value = JSON.parse(bytes.toString('utf8')) as {
342					schemaVersion?: unknown;
343					digest?: unknown;
344				};
345				if (
346					value.schemaVersion !== pinned.schemaVersion ||
347					value.digest !== pinned.digest ||
348					sha256(bytes) !== pinned.sha256
349				)
350					throw new Error(
351						`TinyTranslator bound build receipt identity differs: ${pinned.path}`,
352					);
353				return { ...pinned };
354			}),
355		);
356	}
357	
358	export async function runWitnessAngularTinyTranslator(): Promise<WitnessAngularTinyTranslatorReceipt> {
359		if (
360			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
361			process.env.NPM_CONFIG_OFFLINE !== 'true'
362		)
363			throw new Error('TinyTranslator Witness requires dual offline controls');
364		if (await exists(witnessEvidence))
365			throw new Error('TinyTranslator Witness output collision');
366		const provenance = await verifyLinkedWitnessProvenance(root);
367		const canonicalReceipts = await bindCanonicalReceipts();
368		const lanes = await stageInputs();
369		const runs = await executeRuns(lanes);
370		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
371		const baseline = runs.find((entry) => entry.lane === 'baseline')!;
372		const migrated = runs.find((entry) => entry.lane === 'migrated')!;
373		const artifacts = join(fixtureEvidence, 'witness-artifacts');
374		await mkdir(artifacts, { recursive: true });
375		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
376			flag: 'wx',
377		});
378		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
379			flag: 'wx',
380		});
381		const receipt: WitnessAngularTinyTranslatorReceipt = {
382			schemaVersion: WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA,
383			result: 'pass',
384			fixture: ANGULAR_TINY_TRANSLATOR_FIXTURE,
385			source: ANGULAR_TINY_TRANSLATOR_SOURCE,
386			provenance,
387			canonicalReceipts,
388			runs,
389			mutation,
390			consoleErrors: {
391				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.baseline],
392				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.migrated],
393			},
394			failedRequests: {
395				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.baseline],
396				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.migrated],
397			},
398			mockedSeams: {
399				baseline: [...baseline.mockedNonLoopbackSeams.category],
400				migrated: [...migrated.mockedNonLoopbackSeams.category],
401			},
402			fontSeamDifference: WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE,
403			serviceWorkerAttempt: WITNESS_ANGULAR_TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
404			migratedLaneChain: ANGULAR_TINY_TRANSLATOR_MIGRATED_LANE_CHAIN,
405			migrationFindings: WITNESS_ANGULAR_TINY_TRANSLATOR_MIGRATION_FINDINGS,
406			amendments: WITNESS_ANGULAR_TINY_TRANSLATOR_RECORDED_AMENDMENTS,
407			/**
408			 * The arbitration outcome, read out of the runs rather than declared beside
409			 * them: the obligation the build lanes handed this proof is the one the
410			 * schema publishes, and the numbers are the parse both lanes measured.
411			 */
412			fileReaderArbitration: {
413				state: 'arbitrated-declared-difference',
414				obligation: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS.journeyObligations[0]!,
415				outcome: 'identical-parse-in-both-lanes',
416				parsedUnits: baseline.applicationJourney.fileReaderParity.parsedUnits,
417				parsedDigest: baseline.applicationJourney.fileReaderParity.parsedDigest,
418				inBehaviorDigest: true,
419			},
420			matIconDegradations: {
421				baseline: baseline.applicationJourney.matIcon,
422				migrated: migrated.applicationJourney.matIcon,
423			},
424			renderedStyleParity: {
425				state: 'measured-resolved-styles-with-declared-differences',
426				probes: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES.length,
427				declaredDifferences: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
428				otherProbesAgree: true,
429			},
430			fileInput: {
431				surfaces: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES,
432				fixture: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE,
433				rule: WITNESS_FILE_INPUT_LOAD_RULE,
434			},
435			downloads: {
436				surface: WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE,
437				rule: WITNESS_DOWNLOAD_CAPTURE_RULE,
438				captured: runs.map((entry) => ({
439					lane: entry.lane,
440					pass: entry.pass,
441					files: [...entry.downloadCaptures.captured],
442				})),
443			},
444			persistence: {
445				store: 'browser-local-storage',
446				backend: 'none',
447				stubbed: false,
448				survivesOnlineReload: true,
449			},
450			routeShape: WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
451			scrollAbsence: runs[0]!.scrollAbsence,
452			accommodations: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
453			readiness: {
454				angularLineage: { ready: 1, total: 4, counted: false },
455				overall: { ready: 3, total: 12 },
456			},
457			locality: {
458				mode: 'offline',
459				successfulNonLoopback: 0,
460				osWideIsolation: false,
461				mockedNonLoopbackSeams: migrated.mockedNonLoopbackSeams.category.length,
462			},
463			nonclaims: [...WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS],
464			integrity: { algorithm: 'sha256', canonicalDigest: '' },
465		};
466		receipt.integrity.canonicalDigest = witnessAngularTinyTranslatorDigest(receipt);
467		parseWitnessAngularTinyTranslatorReceipt(receipt);
468		await mkdir(witnessEvidence, { recursive: true });
469		const canonical = canonicalize(receipt);
470		/**
471		 * The companion is rendered from the receipt as PUBLISHED rather than from
472		 * the object in memory: canonicalization sorts keys, so a companion rendered
473		 * from the in-memory object would disagree with the same companion rendered
474		 * from the file, and `verify` — which only ever has the file — would be
475		 * right to reject it.
476		 */
477		const published = parseWitnessAngularTinyTranslatorReceipt(JSON.parse(canonical));
478		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonical}\n`, { flag: 'wx' });
479		await writeFile(
480			join(witnessEvidence, 'receipt.md'),
481			renderWitnessAngularTinyTranslatorReceipt(published),
482			{ flag: 'wx' },
483		);
484		return published;
485	}
486	
487	export async function verifyWitnessAngularTinyTranslator(
488		output = witnessEvidence,
489	): Promise<WitnessAngularTinyTranslatorReceipt> {
490		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
491		const receipt = parseWitnessAngularTinyTranslatorReceipt(
492			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
493		);
494		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
495			throw new Error('TinyTranslator linked Witness provenance differs');
496		for (const bound of receipt.canonicalReceipts)
497			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
498				throw new Error(`TinyTranslator bound build receipt bytes drifted: ${bound.path}`);
499		if (
500			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
501			renderWitnessAngularTinyTranslatorReceipt(receipt)
502		)
503			throw new Error('TinyTranslator human Witness receipt differs');
504		const serialized = canonicalize(receipt);
505		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
506			throw new Error('TinyTranslator receipt leaks host identity');
507		return receipt;
508	}
509	
510	export async function main(args = process.argv.slice(2)): Promise<void> {
511		const publishIndex = args.indexOf('--publish');
512		const verifyIndex = args.indexOf('--verify');
513		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
514			const output = resolve(root, args[publishIndex + 1]!);
515			if (output !== witnessEvidence) throw new Error('TinyTranslator publish path differs');
516			const receipt = await runWitnessAngularTinyTranslator();
517			process.stdout.write(
518				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
519			);
520			return;
521		}
522		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
523			const receipt = await verifyWitnessAngularTinyTranslator(
524				resolve(root, args[verifyIndex + 1]!),
525			);
526			process.stdout.write(
527				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
528			);
529			return;
530		}
531		throw new Error(
532			'TinyTranslator Witness runner requires --run-twice --publish <dir> or --verify <dir>',
533		);
534	}
535	
536	if (basename(process.argv[1] ?? '') === 'angular-tiny-translator-run.ts')
537		main().catch((error: unknown) => {
538			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
539			process.exitCode = 1;
540		});
