/**
 * The CVA round of the `angular-tiny-translator-v0-12-0` cell: the era
 * call-site semantics of `ControlValueAccessor.setDisabledState`, restored.
 *
 * u19h measured a silent typed-data loss on the migrated lane and u19i
 * attributed it: Angular 16's `setUpControl` calls `setDisabledState` on every
 * accessor as it attaches, this application's accessor rebuilds the very
 * `FormGroup` its own debounced subscription is watching, and the edit the user
 * types therefore reaches nothing. Angular 5 called the method only for a
 * control that was already disabled, so on the era cell the body never ran.
 *
 * The repair is the vendor's own switch, provided rather than written:
 * `CALL_SET_DISABLED_STATE` as `'whenDisabledForLegacyCode'`. This driver reads
 * the applied tree's own TypeScript modules and hands them to
 * `@versionless/angular`. It decides which tree is rewritten and nothing else —
 * whether an accessor is one the era guard was hiding is read out of the
 * application's own `setDisabledState` bodies, and where the provider goes is
 * read out of the module that bootstraps.
 */

import { readFile, readdir, writeFile } from 'node:fs/promises';
import * as path from 'pathe';
import {
	ANGULAR_16_BROWSER_CELL,
	declareLegacyCallSetDisabledState,
	type AngularModuleSource,
	type LegacyCallSetDisabledStateDeclaration,
} from '../../../frameworks/angular/src/index.ts';
import { APPLIED_TREE, STAGE_DIRECTORY } from './angular-tiny-translator-apply-run.ts';

/** Every TypeScript module under one tree's `src`, in a stable order. */
export async function readModules(root: string): Promise<readonly AngularModuleSource[]> {
	const modules: AngularModuleSource[] = [];
	const walk = async (directory: string): Promise<void> => {
		for (const entry of await readdir(directory, { withFileTypes: true })) {
			const full = path.join(directory, entry.name);
			if (entry.isDirectory()) {
				await walk(full);
				continue;
			}
			if (path.extname(entry.name) !== '.ts') continue;
			if (entry.name.endsWith('.d.ts') || entry.name.endsWith('.spec.ts')) continue;
			modules.push({ path: path.relative(root, full), source: await readFile(full, 'utf8') });
		}
	};
	await walk(path.join(root, 'src'));
	return Object.freeze(modules.sort((left, right) => (left.path < right.path ? -1 : 1)));
}

export type CvaRound = Readonly<{
	declaration: LegacyCallSetDisabledStateDeclaration;
	modulesRead: number;
	filesChanged: readonly string[];
}>;

/**
 * Apply the forms legacy disabled-state capability to the applied tree.
 *
 * One file can change and no others: the module that bootstraps, which gains an
 * import and one provider. No application logic is touched, and in particular
 * the accessor whose `setDisabledState` is defective is left exactly as its
 * authors wrote it — the migration's job is to stop the framework calling it at
 * a moment the era framework never did, not to repair somebody else's bug.
 */
export async function applyCvaRound(): Promise<CvaRound> {
	const modules = await readModules(APPLIED_TREE);
	const declaration = declareLegacyCallSetDisabledState({
		modules,
		cell: ANGULAR_16_BROWSER_CELL,
	});
	const filesChanged: string[] = [];
	if (declaration.declared && declaration.rootModule !== null) {
		const target = path.join(APPLIED_TREE, declaration.rootModule.path);
		if ((await readFile(target, 'utf8')) !== declaration.rootModule.source) {
			await writeFile(target, declaration.rootModule.source);
			filesChanged.push(declaration.rootModule.path);
		}
	}
	return Object.freeze({
		declaration,
		modulesRead: modules.length,
		filesChanged: Object.freeze(filesChanged),
	});
}

export async function main(): Promise<void> {
	const round = await applyCvaRound();
	await writeFile(
		path.join(STAGE_DIRECTORY, 'cva-round.json'),
		`${JSON.stringify(round, null, '\t')}\n`,
	);
	const legacy = round.declaration.accessors.filter((reading) => reading.legacy);
	process.stdout.write(
		`${String(round.declaration.accessors.length)} custom value accessors in ` +
			`${String(round.modulesRead)} modules; ${String(legacy.length)} legacy\n`,
	);
	process.stdout.write(`declared: ${String(round.declaration.declared)}\n`);
	process.stdout.write(`files changed: ${round.filesChanged.join(', ') || 'none'}\n`);
	for (const refusal of round.declaration.unhandled) process.stdout.write(`refused: ${refusal}\n`);
}

if (process.argv[1]?.endsWith('angular-tiny-translator-cva-run.ts'))
	main().catch((error: unknown) => {
		process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
		process.exitCode = 1;
	});

/**
 * The record of the CVA round: the first migrated TinyTranslator artifact that
 * keeps what a translator types.
 *
 * u19f's `dist-11` mounts, and a browser journey then found the thing a mounting
 * check cannot see — the migrated lane took an edit into a `FormGroup` the view
 * had been detached from, left the outer control pristine, and exported the unit
 * under a changed state with its ORIGINAL text. u19i attributed that
 * mechanically to the application's own `setDisabledState`, woken by Angular
 * 16's `callSetDisabledState: 'always'` default, and the repair is the vendor's
 * own compatibility switch declared by a capability rather than an edit to
 * anybody's logic.
 *
 * Every number here is read at the moment the record is written: the two build
 * logs, both emitted inventories, a browser load of the canonical root, and the
 * two-lane discriminator re-driven by this driver rather than pasted from the
 * round that produced it. This record supersedes u19f by reference — u19f's
 * bytes are unchanged and remain the record of the lane it measured, whose
 * artifact mounts and silently drops typed data.
 */

import { mkdir, readFile, writeFile } from 'node:fs/promises';
import * as path from 'pathe';
import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
import {
	sealRecord,
	verifySealedRecord,
	type SealedRecord,
} from './angular-factoriolab-build-lanes-run.ts';
import { CONSENT } from './angular-tiny-translator-lanes-run.ts';
import { EVIDENCE_DIRECTORY, STAGE_DIRECTORY } from './angular-tiny-translator-apply-run.ts';
import { inventoryOf } from './angular-tiny-translator-final-record.ts';
import { measureDiscriminator } from './angular-tiny-translator-cva-behavior-run.ts';
import { observeAngularTinyTranslatorBoot } from '../witness/angular-tiny-translator-boot-check.ts';
import type { CvaRound } from './angular-tiny-translator-cva-run.ts';

export const UNIT = 'lrapr-t006/u19k-tiny-translator-publish-close';
export const CVA_LANE_FILE = 'u19k-cva-legacy-disabled-state-lane.json';
/** The output root this lane publishes, and the sibling that makes it canonical. */
export const CANONICAL_ROOT = 'dist-13';
export const REPEATED_ROOT = 'dist-14';

async function readBuild(index: number): Promise<Readonly<Record<string, unknown>>> {
	const exit = await readFile(path.join(STAGE_DIRECTORY, `build-${String(index)}.exit`), 'utf8');
	const log = await readFile(
		path.join(STAGE_DIRECTORY, `build-${String(index)}.stdout.log`),
		'utf8',
	);
	return Object.freeze({
		name: `build-${String(index)}`,
		exitStatus: Number.parseInt(exit.trim(), 10),
		command: 'npx ng build --configuration production',
		outputRoot: `dist-${String(index)}`,
		bundleLines: log.split('\n').filter((line) => line.includes('.js')).length,
	});
}

export async function buildCvaLaneRecord(): Promise<SealedRecord> {
	const round = JSON.parse(
		await readFile(path.join(STAGE_DIRECTORY, 'cva-round.json'), 'utf8'),
	) as CvaRound;
	const builds = [await readBuild(13), await readBuild(14)];
	const first = await inventoryOf(path.join(STAGE_DIRECTORY, CANONICAL_ROOT));
	const second = await inventoryOf(path.join(STAGE_DIRECTORY, REPEATED_ROOT));
	const identical = canonical(first) === canonical(second);
	const boot = await observeAngularTinyTranslatorBoot(path.join(STAGE_DIRECTORY, CANONICAL_ROOT));
	const discriminator = await measureDiscriminator();
	const legacy = round.declaration.accessors.filter((reading) => reading.legacy);
	return sealRecord({
		schemaVersion: 'versionless.angular-tiny-translator-cva-lane.v1',
		unit: UNIT,
		consentId: CONSENT,
		result:
			boot.booted && discriminator['agrees'] === true && discriminator['flipped'] === true
				? 'legacy-call-set-disabled-state-declared-build-green-deterministic-and-the-typed-edit-survives'
				: 'legacy-call-set-disabled-state-declared-and-the-lanes-still-disagree',
		meaning:
			'u19f left a migrated artifact that mounts. A browser journey then measured what mounting ' +
			'cannot show: a translation typed into the editor never reached the outer control, the unit ' +
